FROM molecule AS m
INNER JOIN connected AS cm ON m.molecule_id = cm.molecule_id
INNER JOIN bond AS b ON cm.bond_id = b.bond_id
WHERE b.bond_type = ' = ' AND cm.atom_id IN (
    SELECT atom_id FROM atom WHERE element = 'o'
) AND cm.atom_id IN (
    SELECT atom_id FROM atom WHERE element = 'o'
) AND cm.bond_id IN (
    SELECT bond_id FROM bond WHERE bond_type = ' = '
);

